from .stream_enqueuer import StreamEnqueuer
from .timeboxed_reader import TimeboxedReader
from contextlib import contextmanager
from taf.ul.ettf.utils.tshark import RaiseTimeoutError


MAX_TERMINATION_WAIT_TIME = 2.0
MAX_CAPTURING_START_WAIT_TIME = 20


class CommandExecutor(object):
    def __init__(self,
                 capture_cmd,
                 enqueuer_factory=StreamEnqueuer,
                 reader_factory=TimeboxedReader):
        self._process = capture_cmd
        self._enqueuer = None
        self._enqueuer_factory = enqueuer_factory
        self._reader_factory = reader_factory

    def start(self):
        self._process.start()
        self._process.wait_for_capturing_started(timeout=MAX_CAPTURING_START_WAIT_TIME,
                                                 timeout_handling_policy=RaiseTimeoutError())
        try:
            reader = self._reader_factory(self._process.stdout)
            self._enqueuer = self._enqueuer_factory(reader)
            self._enqueuer.start()
        except BaseException:
            self.stop()
            raise

    def stop(self):
        if self._enqueuer is not None:
            self._enqueuer.stop()
            self._enqueuer.join()

        try:
            self._process.stdout.close()
            self._process.stderr.close()
        finally:
            self._process.stop(MAX_TERMINATION_WAIT_TIME)

    @contextmanager
    def get_output(self):
        with self._enqueuer.enqueue() as queue:
            yield queue
